// Shared Undo (plan han-chot-cho-viec, Q5, Q7; PR A step 4–5a). Nothing in the app offers an Undo yet, so these tests call
// offerUndo directly. restore() mutates the list given to loadApp, which is the app's own `todos` array until a remove.
const todo = (title, done = false) => ({ id: `id-${title}`, title, done, createdAt: 1 });
const D5 = due.DUE_TEXT.cleared.replace('{title}', 'A');

test('Undo: offerUndo shows the message and the button; "Hoàn tác" restores, saves, redraws, says D9, hides the button', () => {
  const list = [todo('A')];
  const app = loadApp(list);
  let restored = 0;
  app.ctx.offerUndo(D5, () => { restored++; list.push(todo('B')); });
  assert.equal(app.message(), D5);
  assert.equal(app.undo.shown(), true);
  assert.equal(app.saved.length, 0, 'offering an Undo saves nothing by itself');
  app.undo.click();
  assert.equal(restored, 1);
  assert.deepEqual(app.saved.at(-1).map((t) => t.title), ['A', 'B'], 'the restored list is saved');
  assert.equal(app.count(), '2 việc chưa xong', 'and redrawn');
  assert.equal(app.message(), due.DUE_TEXT.undone);
  assert.equal(app.undo.shown(), false);
  app.undo.click();
  assert.equal(restored, 1, 'a second click does nothing');
  assert.equal(app.saved.length, 1);
});

test('Undo: the button goes after 10 seconds, and the message stays (A16)', () => {
  const app = loadApp([todo('A')]);
  let restored = 0;
  app.ctx.offerUndo(D5, () => restored++);
  assert.equal(app.timers.at(-1).ms, 10000);
  app.runTimers();
  assert.equal(app.undo.shown(), false);
  assert.equal(app.message(), D5);
  app.undo.click();
  assert.equal(restored, 0);
  assert.equal(app.saved.length, 0);
});

