  const cases = {
    add: (app) => app.submit('C'),
    toggle: (app) => app.row('A').children.input.onchange(),
    remove: (app) => app.row('A').children.button.onclick(),
    import: (app) => app.pick({ size: 0, text: async () => '' }),
  };
  for (const [name, act] of Object.entries(cases)) {
    const app = loadApp([todo('A'), todo('B')]);
