// Static checks on app/ files (plan/2026-10-19-khach-khong-mat-viec.md, commit B). Run: node --test
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const read = (f) => fs.readFileSync(path.join(__dirname, '..', 'app', f), 'utf8');
const html = read('index.html');

// Was store, backup, app; due.js comes before backup.js and app.js, which use it (plan han-chot-cho-viec, Q2).
test('scripts load in the order store, due, backup, app (Q2)', () => {
  const scripts = [...html.matchAll(/<script\b[^>]*\bsrc="([^"]+)"/g)].map((m) => m[1]);
  assert.deepEqual(scripts, ['store.js', 'due.js', 'backup.js', 'app.js']);
});

test('the Undo button sits hidden in the live notices area, with the text of D6 (plan han-chot-cho-viec, Q5, Q7)', () => {
  const { DUE_TEXT } = require('../app/due.js');
  assert.match(html, /<div id="notices" role="status" aria-live="polite">[\s\S]*<button type="button" id="undo" hidden>([^<]*)<\/button>\s*<\/div>/);
  assert.equal(html.match(/id="undo" hidden>([^<]*)</)[1], DUE_TEXT.undo);
});

test('no UTC day: app.js and due.js never call toISOString (A9)', () => {
  for (const f of ['app.js', 'due.js']) assert.doesNotMatch(read(f), /toISOString/, f);
});

test('index.html loads nothing from outside (AC26, S4)', () => {
  assert.doesNotMatch(html, /\b(src|href)\s*=\s*["']?\s*(https?:)?\/\//i);
});

test('only store.js touches browser storage', () => {
  for (const f of ['app.js', 'backup.js', 'due.js']) assert.doesNotMatch(read(f), /localStorage/, f);
});

test('the main screen says where the list is kept, and has the new controls (AC23, U5)', () => {
  assert.ok(html.includes(
    'Danh sách chỉ được lưu trên trình duyệt này, nên xoá dữ liệu trang web, đổi trình duyệt hoặc đổi máy là mất, trừ khi bạn đã sao lưu ra file.'));
  assert.ok(html.includes('>Sao lưu ra file</button>'));
  assert.match(html, /<label[^>]*>Nhập từ file<input type="file"/);
  assert.match(html, /role="status"/);
  assert.match(html, /<dialog id="confirm" aria-labelledby="confirm-text">/);
});

test('confirm dialog buttons show a focus ring on any focus, not only :focus-visible (U5, PR 1)', () => {
  // Firefox gives the autofocused "Huỷ" no ring after the file picker closes: its :focus-visible heuristic
  // does not count that focus as keyboard focus. A rule on plain :focus does not depend on that heuristic.
  const css = read('style.css');
  assert.match(css, /dialog button:focus\s*\{[^}]*outline:\s*2px solid/);
});

test('visible text in index.html has no technical words (AC24, U4)', () => {
  const text = html.replace(/<script[\s\S]*?<\/script>/g, '').replace(/<[^>]+>/g, ' ');
  assert.doesNotMatch(text, /localStorage|JSON|console/i);
});
